// Atlas — 197 real world maps (1784–2015) to date by eye.
// Rescued from the original game, "Atlas, When?", at atlas-when.karminker.chatgpt.site on
// 2026-10-26 and checked character-for-character against it. Scans stream
// from the Library of Congress and David Rumsey Map Collection IIIF servers;
// nothing here is hosted by Globalio. Decoded by src/utils/atlasWhen.ts.
//
// Clue texts, clue sources and hints repeat across maps, so they live once in
// STRINGS and each map points into it by index.

/** [id, year, title, [source host, source path], hint, clues [[text, source?]],
 *  referenceClues, rights, maker, publisher, collection, credit,
 *  [IIIF host, service (0 = the map id), region, base], redactions] */
export type AtlasRow = [
  string, number, string, [number, string], number, ([number, number] | [number])[],
  number, number, string | string[] | null, string | string[], number, number,
  [number, string | 0, number[], number[]], number[][],
]

